declare cid uuid;
begin
  select id into cid from public.courses where slug = 'spanish-2';
  if cid is null then raise exception 'Run the course file first'; end if;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 11, $j$3.3 Comparisons and Superlatives$j$, $j${"readings": [{"title": "Proverbs 16 (King James Version)", "url": "/portal/bible/Proverbs/16"}], "body": "Proverbs 16:16 says, How much better is it to get wisdom than gold! and to get understanding rather to be chosen than silver! This verse compares two things, and Spanish has clear patterns for that.\n\nTo say more or less, use más or menos plus the adjective plus que. Mi hermano es más alto que yo. Esta clase es menos difícil que la otra. To say equal, use tan plus the adjective plus como. Soy tan alto como tú. For nouns, use tanto, tanta, tantos or tantas plus the noun plus como. Tengo tantos libros como tú. Tengo tantas amigas como ellos. Before a number, use de instead of que: Tengo más de veinte libros.\n\nSome adjectives have irregular comparisons: bueno becomes mejor, malo becomes peor, joven becomes menor, viejo becomes mayor. Mi hermano mayor es mejor cantante que yo.\n\nFor the superlative, the most or the least, use el, la, los or las plus más or menos plus the adjective plus de. Es la chica más amable de la clase. Es el mejor libro de la biblioteca. The ending ísimo means very: altísimo, buenísimo.\n\nWorked example: Mi iglesia es más grande que mi escuela, pero mi escuela es tan bonita como mi iglesia. Common mistake: Más mejor. Mejor already means better, so do not add más.\n\nYour task: (1) Compare yourself with a family member in four sentences. (2) Write three superlative sentences about your school, church and city.\n\nFlorida standards: Florida World Languages standards, Level 2 (WL.K12.NH, WL.K12.IL).", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Florida World Languages standards, Level 2 (WL.K12.NH, WL.K12.IL)", "script": "Welcome back. Listen, Proverbs 16:16 says, How much better is it to get wisdom than gold! This verse compares two things.\n\nNow watch this. More or less: más or menos plus the adjective plus que. Mi hermano es más alto que yo.\n\nEqual: tan plus the adjective plus como. Soy tan alto como tú. For nouns, tanto, tanta, tantos, tantas. Tengo tantos libros como tú.\n\nBefore a number, use de. Tengo más de veinte libros.\n\nIrregular: mejor, peor, mayor, menor. Do not say más mejor.\n\nSuperlative: el, la, los, las plus más plus the adjective plus de. Es la chica más amable de la clase.\n\nYour task is to compare yourself with a relative and write three superlative sentences. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.3 Comparisons and Superlatives$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 12, $j$3.4 Por and Para$j$, $j${"readings": [{"title": "Jeremiah 29 (King James Version)", "url": "/portal/bible/Jeremiah/29"}], "body": "Jeremiah 29:11 says, For I know the thoughts that I think toward you, saith the LORD, thoughts of peace, and not of evil, to give you an expected end. English uses for for many ideas. Spanish divides them between por and para.\n\nUse para for purpose, goal or destination. Estudio para aprender means I study in order to learn. Este regalo es para ti means this gift is for you. Salgo para Miami means I leave for Miami. La tarea es para el lunes means the homework is due Monday. Trabajo para una iglesia means I work for a church. Para mí means in my opinion.\n\nUse por for cause, movement through a place, a length of time, an exchange and on behalf of. Gracias por la ayuda means thanks for the help. Caminé por el parque means I walked through the park. Estudié por dos horas means I studied for two hours. Pagué diez dólares por el libro means I paid ten dollars for the book. Oro por mi familia means I pray for my family. Por la mañana means in the morning.\n\nA helpful tip: para looks forward to a goal, and por looks back at a reason.\n\nWorked example: Voy a la iglesia para orar, y doy gracias por la comida. Common mistake: using para for duration. Say Viví allí por dos años.\n\nYour task: (1) Write six sentences, three with por and three with para. (2) Explain which meaning of each preposition you used.\n\nFlorida standards: Florida World Languages standards, Level 2 (WL.K12.NH, WL.K12.IL).", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Florida World Languages standards, Level 2 (WL.K12.NH, WL.K12.IL)", "script": "Welcome back. Listen, Jeremiah 29:11 says, I know the thoughts that I think toward you, saith the LORD, thoughts of peace. English uses for for many ideas. Spanish divides them between por and para.\n\nNow watch this. Para is purpose, goal or destination, deadlines and recipients. Estudio para aprender. Este regalo es para ti. Salgo para Miami.\n\nPor is cause, movement through, time, exchange and on behalf of. Gracias por la ayuda. Caminé por el parque. Estudié por dos horas. Oro por mi familia.\n\nHere is a tip. Para looks forward to a goal. Por looks back at a reason.\n\nYour task is to write six sentences with por and para and explain each choice. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.4 Por and Para$j$);
end
$seed$;
